def sum_all(*args):
    return sum(args)

def print_info(**kwargs):
    for key, value in kwargs.items():
        print(f"  {key}: {value}")

def combine(prefix, *args, suffix='', **kwargs):
    print(f"{prefix} {sum(args)} {suffix}")
    if kwargs:
        print("Extra info:")
        print_info(**kwargs)

print(f"Sum: {sum_all(1, 2, 3, 4, 5)}")
print_info(name='Bob', age=25, role='Developer')
combine('Result:', 10, 20, 30, suffix='is the total', status='complete')

